const CC = { a: "text-mc-green", b: "text-mc-aqua", c: "text-mc-red", e: "text-mc-yellow", 6: "text-mc-gold", 7: "text-mc-gray", 4: "text-mc-dark-red", f: "text-mc-white" }
function mcText(str) { const p = h("p", "truncate"); for (const part of str.split("§").filter(Boolean)) p.append(h("span", CC[part[0]] || "", part.slice(1))); return p }
function icon32(block, overlay, overlayHover) {
  const ic = h("div", "mc-tile relative size-16 shrink-0")
  ic.style.setProperty("--mc-tile", `var(--mc-${SPR[block] ? block : "block-dirt"})`); ic.style.setProperty("--mc-tile-size", "calc(32 * var(--mc-px))")
  if (overlay) { const o = sprite(overlay, "mc-sprite absolute inset-0 hidden group-hover:block"); if (overlayHover) o.dataset.spriteHover = overlayHover; ic.append(o) }
  return ic
}
function pingLoop(el) { let k = 1; setInterval(() => { if (document.body.classList.contains("mc-anim-paused")) return; k = (k % 5) + 1; el.dataset.sprite = `server-list-pinging-${k}`; setSprite(el, el.dataset.sprite) }, 120) }
for (const [name, motd, players, ping, block] of [
  ["Kaizen Network", "§aSurvival §7· §bSkyblock §7· §6Events", "142/500", 5, "block-grass-block-side-tinted"],
  ["Big network", "§eThousands of players §c(made up)", "48,211/100,000", 4, "block-gold-block"],
  ["Friends' server", "§7Vanilla 26.2", "3/10", 3, "block-oak-planks"],
  ["Old server", "§cIncompatible version", "", "incompatible", "block-cobblestone"],
  ["Ghost server", "§4Can't connect to server", "", "unreachable", "block-netherrack"],
  ["New server", "§7Pinging...", "", "pinging", "block-glass"],
]) {
  const row = h("div", "group flex cursor-pointer items-center gap-2 border border-transparent p-0.5 hover:border-mc-gray")
  const mid = h("div", "min-w-0 flex-1"); mid.append(h("p", "truncate", name), mcText(motd))
  const right = h("div", "flex shrink-0 items-center gap-1 self-start"); right.append(h("span", "text-xs text-mc-gray", players))
  const ps = sprite(typeof ping === "number" ? `server-list-ping-${ping}` : ping === "pinging" ? "server-list-pinging-1" : `server-list-${ping}`)
  if (ping === "pinging") pingLoop(ps)
  right.append(ps)
  row.append(icon32(block, "server-list-join", "server-list-join-highlighted"), mid, right); $("#servers").append(row)
}
