const ANIMATED_TILES = { "block-water": "mc-anim-water", "block-lava": "mc-anim-lava", "block-magma": "mc-anim-magma", "block-sculk": "mc-anim-sculk" }
for (const name of Object.keys(SPR).filter((n) => n.startsWith("block-") && !n.includes("-strip"))) {
  const anim = ANIMATED_TILES[name]
  const b = h("button", `${anim || "mc-tile"} flex aspect-square items-end p-0.5 text-left text-xs leading-none outline-none focus-visible:mc-focus-ring`)
  if (anim) b.style.setProperty("--mc-anim-size", "calc(32 * var(--mc-px))")
  else { b.style.setProperty("--mc-tile", `var(--mc-${name})`); b.style.setProperty("--mc-tile-size", "calc(32 * var(--mc-px))") }
  b.title = name
  const lb = h("span", "mc-bg-list w-full truncate px-0.5", label(name) + (anim ? " ▶" : "")); lb.dataset.noi18n = "1"
  b.append(lb)
  b.addEventListener("click", () => copy(anim || `mc-tile [--mc-tile:var(--mc-${name})]`))
  $("#blocks").append(b)
}
{
  const FAMILIES = [["All", ""], ["Items", "item-"], ["Blocks", "block-"], ["HUD", "hud-"], ["Widgets", "widget-"], ["Containers", "container-"], ["Advancements", "advancements-"], ["Boss", "boss-bar-"], ["Icons", "icon-"], ["Toasts", "toast-"], ["Recipes", "recipe-book-"], ["Lists", "server-list-|world-list-|transferable-list-|player-list-"], ["Stats", "statistics-|spectator-"], ["GUI", "gui-|popup-|tooltip|panel-|notification-|pause-menu-|dialog-"]]
  const grid = $("#sprite-grid"), q = $("#sprite-q"); let fam = ""
  grid.dataset.noi18n = "1"
  const names = Object.keys(SPR).filter((n) => !SPR[n][2] && !n.includes("-strip")).sort()
  const cells = names.map((n) => {
    const [w, hh] = SPR[n]
    const b = h("button", "flex flex-col items-center justify-between gap-1 p-1 text-xs outline-none hover:bg-accent focus-visible:mc-focus-ring")
    b.title = `--mc-${n} · ${w}×${hh}`; b.dataset.name = n
    const box = h("span", "flex h-[calc(40*var(--mc-px))] w-full items-center justify-center overflow-hidden")
    const z = Math.max(w, hh) <= 13 ? 3 : Math.max(w, hh) <= 20 ? 2 : 1
    const s = sprite(n, "mc-sprite", z > 1 ? String(z) : null)
    if (w > 50 || hh > 40) s.dataset.zoom = String(Math.min(50 / w, 40 / hh).toFixed(3))
    box.append(s); b.append(box, h("span", "w-full truncate text-center text-muted-foreground", n))
    b.addEventListener("click", () => copy(`mc-sprite [--mc-sprite:var(--mc-${n})] [--mc-sprite-w:${w}] [--mc-sprite-h:${hh}]`))
    grid.append(b); return b
  })
  const count = $("#sprite-count"); let shown = 0
  const renderCount = live(count, () => `${shown} sprites`)
  const filter = () => {
    const term = q.value.trim().toLowerCase(), re = fam ? new RegExp(`^(${fam})`) : null; shown = 0
    for (const c of cells) { const ok = (!re || re.test(c.dataset.name)) && c.dataset.name.includes(term); c.hidden = !ok; if (ok) shown++ }
    renderCount()
  }
  for (const [lbl, pre] of FAMILIES) {
    const chip = h("button", "fam mc-button outline-none hover:mc-button-highlighted focus-visible:mc-button-highlighted px-2 pt-0.5 pb-1 text-xs", lbl)
    chip.addEventListener("click", () => { fam = pre; $$(".fam").forEach((c) => c.classList.toggle("mc-tint-green", c === chip)); filter() })
    if (!pre) chip.classList.add("mc-tint-green")
    $("#sprite-families").append(chip)
  }
  q.addEventListener("input", filter); filter()
}

